def is_nested(string):
    open_count = 0
    for char in string:
        if char == '[':
            open_count += 1
        elif char == ']':
            if open_count > 0:
                open_count -= 1
            else:
                return False

    # Check for nesting
    nested = False
    current_depth = 0
    for char in string:
        if char == '[':
            current_depth += 1
            if current_depth > 1:
                nested = True
        elif char == ']':
            current_depth -= 1

    return nested

